/* Educational movement library. Subdivisions change emphasis, never imply isolation. */
const EXERCISES = {
 chinNod:{name:'Gentle chin nod',equipment:'Bodyweight · folded towel',sets:'5 slow repetitions · comfortable range',steps:['Lie on your back with a small folded towel supporting your head.','Make a small, gentle nod as if saying yes. Keep your head supported rather than lifting it.','Relax fully between repetitions and breathe normally.'],tip:'This is a motor-control exercise for the deep neck flexors, not a heavy neck curl. Stop if it causes pain or dizziness.'},
 neckFrontHold:{name:'Gentle neck flexion isometric',equipment:'Bodyweight · hand resistance',sets:'3–5 gentle holds · 3–5 seconds',steps:['Sit tall with your head in a comfortable neutral position and shoulders relaxed.','Place a palm on your forehead. Press very lightly into your hand without letting your head move.','Keep breathing, release, and rest between holds.'],tip:'Use gentle effort. Both SCM heads and other neck flexors work together. Avoid neck bridges and heavy resistance.'},
 neckSideHold:{name:'Gentle neck side isometric',equipment:'Bodyweight · hand resistance',sets:'3 gentle holds per side · 3–5 seconds',steps:['Sit upright with your head centered and your shoulders relaxed.','Place a hand against the side of your head above the ear. Press very gently sideways while the hand prevents movement.','Release, rest, and repeat on the other side without tilting or twisting.'],tip:'Keep the effort light and comfortable. This trains several neck muscles together rather than isolating one SCM head.'},
 neckBackHold:{name:'Gentle neck extension isometric',equipment:'Bodyweight · hand resistance',sets:'3–5 gentle holds · 3–5 seconds',steps:['Sit tall and place your hands behind your head.','Press your head gently backward into your hands without moving or tipping your chin upward.','Breathe normally, release, and rest between holds.'],tip:'Use light pressure and a neutral head position. If you have an existing neck problem, ask a qualified clinician about suitable loading.'},
 inclineCurl:{name:'Incline dumbbell curl',equipment:'Dumbbells · incline bench',sets:'2–3 sets · 8–12 reps',steps:['Set the bench to a gentle incline. Sit back with your arms hanging naturally.','Keep your upper arms steady and curl with palms turning upward.','Lower slowly through a comfortable range. Avoid swinging or forcing the shoulder back.'],tip:'Shoulder extension puts the biceps in a longer position; both heads still contribute.'},
 preacherCurl:{name:'Preacher curl',equipment:'Dumbbell or EZ bar · preacher bench',sets:'2–3 sets · 10–15 reps',steps:['Rest your upper arms on the pad and keep your shoulders relaxed.','Curl upward without lifting your elbows from the support.','Lower under control and stop before a painful or forced elbow lockout.'],tip:'A supported curl with the shoulder forward. It trains both biceps heads.'},
 cableCurl:{name:'Standing cable curl',equipment:'Cable machine · straight bar',sets:'2–3 sets · 10–15 reps',steps:['Stand tall, grasp the handle with palms up, and keep elbows near your sides.','Curl without leaning back or moving your upper arms.','Pause briefly and lower with control.'],tip:'Choose a load that leaves about 1–3 good repetitions in reserve.'},
 hammerCurl:{name:'Hammer curl',equipment:'Dumbbells',sets:'2–3 sets · 10–15 reps',steps:['Hold the dumbbells beside your hips with your thumbs pointing forward.','Bend your elbows, keeping the neutral grip and your torso still.','Lower slowly; keep wrists straight.'],tip:'Trains the brachialis, brachioradialis and biceps together.'},
 flatPress:{name:'Dumbbell bench press',equipment:'Dumbbells · flat bench',sets:'2–3 sets · 8–12 reps',steps:['Lie on the bench, plant your feet and hold the dumbbells above your chest.','Lower with elbows roughly 30–60° from your body.','Press upward without bouncing or lifting your hips.'],tip:'Use a comfortable depth and keep your wrists stacked over your forearms.'},
 inclinePress:{name:'Incline dumbbell press',equipment:'Dumbbells · incline bench',sets:'2–3 sets · 8–12 reps',steps:['Set the bench to a modest 15–30° incline. Keep feet planted.','Lower the dumbbells toward the upper chest with forearms upright.','Press upward smoothly while keeping your shoulders comfortable.'],tip:'An incline can shift emphasis toward the clavicular region; the rest of the chest still works.'},
 pushUp:{name:'Push-up',equipment:'Bodyweight',sets:'2–3 sets · 6–15 reps',steps:['Place your hands just wider than your shoulders and brace your body in a straight line.','Lower your chest toward the floor with elbows angled slightly back.','Push the floor away. Use an elevated surface to make the movement easier.'],tip:'End the set when you can no longer keep a controlled, rigid body position.'},
 lateralRaise:{name:'Dumbbell lateral raise',equipment:'Dumbbells',sets:'2–3 sets · 12–20 reps',steps:['Stand tall with light dumbbells and slightly bent elbows.','Raise your arms a little forward of directly sideways, toward shoulder height.','Lower without shrugging or swinging.'],tip:'Lead with the elbows and use a comfortable range.'},
 shoulderPress:{name:'Seated shoulder press',equipment:'Dumbbells · upright bench',sets:'2–3 sets · 8–12 reps',steps:['Sit with back support and dumbbells near shoulder height.','Press overhead while keeping ribs stacked over your pelvis.','Lower slowly to a comfortable depth without arching your lower back.'],tip:'The anterior and middle deltoids work with your triceps.'},
 reverseFly:{name:'Chest-supported reverse fly',equipment:'Dumbbells · incline bench',sets:'2–3 sets · 12–20 reps',steps:['Lie chest down on an incline bench with light dumbbells.','Move your arms outward with a soft bend in the elbows.','Lower with control and avoid shrugging.'],tip:'Focus on moving the upper arms; do not force the shoulder blades together.'},
 overheadExtension:{name:'Overhead cable extension',equipment:'Cable machine · rope',sets:'2–3 sets · 10–15 reps',steps:['Face away from the cable with hands overhead and elbows bent.','Brace your trunk and extend your elbows without flaring your ribs.','Return slowly into a comfortable stretch.'],tip:'An overhead position lengthens the triceps long head; all three heads extend the elbow.'},
 pushdown:{name:'Cable triceps pushdown',equipment:'Cable machine · rope',sets:'2–3 sets · 10–15 reps',steps:['Stand tall with elbows held comfortably near your sides.','Extend your elbows and move the handle toward your thighs.','Return under control while keeping your upper arms steady.'],tip:'Avoid using your torso to move the load.'},
 closePushup:{name:'Close-grip incline push-up',equipment:'Bodyweight · stable elevated surface',sets:'2–3 sets · 8–15 reps',steps:['Place your hands around shoulder width on a sturdy elevated surface.','Keep your body braced and lower with elbows close to your sides.','Press up without letting the hips sag.'],tip:'A comfortable narrow grip adds triceps demand; hands do not need to form a diamond.'},
 wristCurl:{name:'Supported wrist curl',equipment:'Light dumbbell · bench',sets:'2 sets · 12–20 reps',steps:['Support your forearm on a bench with your palm facing upward.','Let the wrist move into a comfortable extended position.','Curl the wrist up slowly without moving your forearm.'],tip:'Use a light load and stop if you feel wrist pain.'},
 reverseWrist:{name:'Reverse wrist curl',equipment:'Light dumbbell · bench',sets:'2 sets · 12–20 reps',steps:['Support your forearm with palm facing down and wrist over the edge.','Lift the back of your hand toward your forearm.','Lower slowly through a comfortable range.'],tip:'A small range and light weight are enough for these muscles.'},
 crunch:{name:'Controlled crunch',equipment:'Bodyweight · mat',sets:'2–3 sets · 10–20 reps',steps:['Lie on your back with knees bent and feet on the floor.','Exhale and lift your shoulder blades, gently bringing ribs toward pelvis.','Lower slowly without pulling on your neck.'],tip:'The rectus abdominis works as a whole; upper and lower portions are regions, not separate muscles.'},
 deadBug:{name:'Dead bug',equipment:'Bodyweight · mat',sets:'2–3 sets · 6–10 reps per side',steps:['Lie on your back with arms upward and hips and knees bent to 90°.','Keep your ribs down and slowly extend one arm and the opposite leg.','Return before your back arches, then switch sides.'],tip:'Move only as far as you can while keeping your trunk controlled.'},
 sidePlank:{name:'Side plank',equipment:'Bodyweight · mat',sets:'2–3 sets · 15–30 sec per side',steps:['Lie on your side with your elbow under your shoulder.','Lift your hips, keeping your body in a straight line.','Breathe steadily. Bend the knees to reduce the difficulty.'],tip:'Works the lateral trunk as well as the hip stabilizers.'},
 pallof:{name:'Pallof press',equipment:'Cable machine or resistance band',sets:'2–3 sets · 8–12 reps per side',steps:['Stand side-on to a securely anchored band or cable at chest height.','Hold the handle at your chest, then press straight forward.','Resist turning toward the anchor and return slowly.'],tip:'The goal is to resist rotation, not to twist against the load.'},
 squat:{name:'Goblet squat',equipment:'Dumbbell or kettlebell',sets:'2–3 sets · 8–12 reps',steps:['Hold the weight at your chest with feet in a comfortable stance.','Sit down between your hips, allowing knees to travel with your toes.','Stand through the whole foot while keeping your torso braced.'],tip:'Use a depth you can control without pain; no squat isolates one quadriceps head.'},
 splitSquat:{name:'Supported split squat',equipment:'Dumbbells · stable support',sets:'2–3 sets · 8–12 reps per side',steps:['Take a split stance and use a stable support for balance.','Lower your back knee toward the floor while bending the front knee.','Push through the front foot to stand; keep the movement controlled.'],tip:'Keep the stance wide enough for balance, as if standing on train tracks.'},
 legExtension:{name:'Leg extension',equipment:'Leg extension machine',sets:'2–3 sets · 10–15 reps',steps:['Align the machine pivot with your knee and place the pad above your ankle.','Extend your knee smoothly without kicking the weight.','Lower slowly through a comfortable range.'],tip:'Trains knee extension, including the rectus femoris; foot angle does not isolate the inner quadriceps.'},
 standingCalf:{name:'Standing calf raise',equipment:'Stable support · bodyweight or machine',sets:'2–3 sets · 10–20 reps',steps:['Stand with knees mostly straight and hold a stable support.','Rise onto the balls of your feet without rolling your ankles.','Lower slowly into a comfortable stretch and avoid bouncing.'],tip:'Straight-knee raises train the gastrocnemius and soleus.'},
 seatedCalf:{name:'Seated calf raise',equipment:'Seated calf machine',sets:'2–3 sets · 12–20 reps',steps:['Sit with knees bent and the pad resting on your thighs.','Raise your heels while keeping the balls of your feet supported.','Lower slowly and pause briefly at the bottom.'],tip:'Bent knees reduce the gastrocnemius contribution, increasing relative soleus emphasis.'},
 pulldown:{name:'Lat pulldown',equipment:'Cable machine · pulldown bar',sets:'2–3 sets · 8–12 reps',steps:['Grip the bar comfortably and secure your legs under the pad.','Pull elbows toward your sides and bring the bar toward your upper chest.','Let your arms rise under control without swinging or pulling behind your neck.'],tip:'A very wide grip is not necessary for lat development.'},
 row:{name:'Chest-supported row',equipment:'Dumbbells · incline bench',sets:'2–3 sets · 8–12 reps',steps:['Lie chest-down on an incline bench and let your arms hang.','Pull the elbows back while keeping your chest on the pad.','Lower with control, allowing a comfortable reach at the bottom.'],tip:'Rows train multiple upper-back muscles along with the arms.'},
 shrug:{name:'Dumbbell shrug',equipment:'Dumbbells',sets:'2–3 sets · 10–15 reps',steps:['Stand tall with dumbbells at your sides.','Lift your shoulders toward your ears without rolling them.','Pause briefly and lower slowly.'],tip:'Keep the neck neutral and avoid using momentum.'},
 birdDog:{name:'Bird dog',equipment:'Bodyweight · mat',sets:'2–3 sets · 6–10 reps per side',steps:['Start on hands and knees with a neutral spine.','Reach one arm and the opposite leg away without rotating your pelvis.','Pause, return slowly, then change sides.'],tip:'This is a trunk control exercise; external load can be progressed only when control is consistent.'},
 hipThrust:{name:'Hip thrust',equipment:'Bench · bodyweight or padded barbell',sets:'2–3 sets · 8–12 reps',steps:['Support your upper back on a stable bench and plant your feet.','Lift your hips until the trunk and thighs form a line.','Keep your ribs down, then lower without arching the lower back.'],tip:'Aim for hip extension rather than a larger movement through your spine.'},
 hipAbduction:{name:'Side-lying hip abduction',equipment:'Bodyweight · mat or light band',sets:'2–3 sets · 12–20 reps per side',steps:['Lie on your side with the bottom knee bent and top leg straight.','Raise the top leg slightly without turning your pelvis upward.','Lower slowly. Keep the toes pointing roughly forward.'],tip:'Targets the hip abductors, including gluteus medius and minimus.'},
 rdl:{name:'Romanian deadlift',equipment:'Dumbbells or barbell',sets:'2–3 sets · 8–12 reps',steps:['Stand with a soft knee bend and the weight close to your thighs.','Push your hips back while keeping your spine controlled and the weight close.','Stop at a comfortable hamstring stretch, then drive the hips forward to stand.'],tip:'Keep the knee angle fairly steady; range is determined by control, not by reaching the floor.'},
 legCurl:{name:'Seated leg curl',equipment:'Seated leg curl machine',sets:'2–3 sets · 10–15 reps',steps:['Adjust the machine so the knee lines up with the pivot and secure the thigh pad.','Bend your knees to pull the pad down and back.','Return slowly without letting the weight stack slam.'],tip:'Trains the hamstrings through knee flexion, including the biceps femoris short head.'}
};
const part=(name,description,moves)=>({name,description,moves});
const MUSCLES={
 neck:{name:'Neck',latin:'Sternocleidomastoid & cervical stabilizers',description:'The muscles around your neck turn, tilt and support your head. Superficial movers and deeper stabilizers work together.',growth:'Build neck training gradually with light, controlled resistance. Gentle nods develop control; comfortable isometrics provide a starting strength stimulus. Heavier neck training needs individual guidance. Do not force end-range positions or train through pain or dizziness.',parts:[part('SCM · sternal head','The sternocleidomastoid’s narrower sternal head begins at the upper breastbone. Together with its clavicular head, it helps turn the face to the opposite side and tilt the head toward the same side.',['neckFrontHold','neckSideHold']),part('SCM · clavicular head','The broader clavicular head begins at the inner collarbone and joins the sternal head near the skull behind the ear. The heads work together; these exercises do not isolate one head.',['neckSideHold','neckFrontHold']),part('Deep neck flexors','Longus colli and longus capitis sit deep at the front of the cervical spine. They help control neck position and support small flexion movements.',['chinNod','neckFrontHold']),part('Posterior neck muscles','Splenius, semispinalis and other posterior cervical muscles help extend, rotate and stabilize the head. A gentle extension hold loads them together.',['neckBackHold','chinNod'])]},
 biceps:{name:'Biceps',latin:'Biceps brachii',description:'The two-headed muscle at the front of your upper arm. It bends your elbow and turns your palm upward.',growth:'Train elbow flexion with control through a comfortable range. Combine a shoulder-forward curl with a shoulder-back variation for varied loading.',parts:[part('Long head','The outer head starts above the shoulder socket. It crosses the shoulder and elbow, helping bend the elbow and rotate the palm upward.',['inclineCurl','cableCurl']),part('Short head','The inner head begins at the coracoid process of the shoulder blade. It works alongside the long head in curls and palm-up rotation.',['preacherCurl','cableCurl']),part('Brachialis','A separate muscle beneath the biceps. It bends the elbow regardless of palm position and contributes to upper-arm thickness.',['hammerCurl','preacherCurl'])]},
 chest:{name:'Chest',latin:'Pectoralis major',description:'Brings the upper arm across the body and assists pressing. Its regions share a broad tendon on the upper arm.',growth:'Use a flat press and a modest incline press for varied regional loading. Progress repetitions before adding weight.',parts:[part('Clavicular region','The upper region originates at the collarbone and helps lift the arm forward and bring it across your body.',['inclinePress','pushUp']),part('Sternocostal region','The broad middle and lower region originates at the breastbone and ribs. It contributes strongly to pressing and bringing the arm inward.',['flatPress','pushUp'])]},
 shoulders:{name:'Shoulders',latin:'Deltoid',description:'Three regions move the upper arm forward, out to the side and backward. The rotator cuff supports shoulder stability.',growth:'Combine a press, a lateral raise and a rear-deltoid movement. Use controlled loads, especially for raises.',parts:[part('Anterior deltoid','The front region lifts the upper arm forward and assists overhead and chest pressing.',['shoulderPress','inclinePress']),part('Middle deltoid','The lateral region is a main contributor to lifting your arm away from your side.',['lateralRaise','shoulderPress']),part('Posterior deltoid','The rear region helps move the arm backward and outward, working during rows and reverse flies.',['reverseFly','row'])]},
 triceps:{name:'Triceps',latin:'Triceps brachii',description:'Three heads at the back of your upper arm straighten your elbow. The long head also crosses the shoulder.',growth:'Combine an overhead extension with an arm-at-side movement. All heads contribute to elbow extension; no grip switches one head off.',parts:[part('Long head','Begins at the shoulder blade and crosses the shoulder and elbow. Raising your arm overhead puts this head in a longer position.',['overheadExtension','pushdown']),part('Lateral head','The outer head originates on the upper arm. It helps extend your elbow during pressing and extensions.',['pushdown','closePushup']),part('Medial head','This deeper head assists elbow extension across a wide range of force demands. It works with the other two heads.',['pushdown','overheadExtension'])]},
 forearms:{name:'Forearms',latin:'Forearm flexors & extensors',description:'A group of muscles that move the wrist, fingers and forearm. They support grip and stabilize your hands under load.',growth:'Build gradually with light wrist work and neutral-grip curls. Allow recovery from heavy gripping across the rest of your training.',parts:[part('Wrist flexors','On the palm side, these muscles bend the wrist and assist finger flexion and grip.',['wristCurl','hammerCurl']),part('Wrist extensors','On the back of the forearm, these muscles extend the wrist and stabilize it when gripping.',['reverseWrist','hammerCurl']),part('Brachioradialis','A prominent muscle on the thumb side of the forearm. It bends the elbow, particularly with a neutral grip.',['hammerCurl','cableCurl'])]},
 abs:{name:'Abdominals',latin:'Rectus abdominis & transversus abdominis',description:'Your trunk muscles help move and stabilize your spine and manage pressure around your torso.',growth:'Progress controlled trunk flexion and stability work. Ab training builds muscle; visible definition also depends on overall body composition.',parts:[part('Rectus abdominis','The paired “six-pack” muscle brings the ribs and pelvis closer. Upper and lower areas are regions of one continuous muscle.',['crunch','deadBug']),part('Transversus abdominis','The deep abdominal layer helps manage abdominal pressure and stabilize the trunk during breathing and movement.',['deadBug','birdDog'])]},
 obliques:{name:'Obliques',latin:'External & internal obliques',description:'The muscles along the sides of the torso rotate and side-bend your trunk and help resist unwanted movement.',growth:'Use anti-rotation and lateral stability work. Progress resistance or hold time while keeping your trunk controlled.',parts:[part('External obliques','The outer layer helps rotate the torso to the opposite side and bends the trunk sideways. It also braces the abdomen.',['pallof','sidePlank']),part('Internal obliques','The deeper layer helps rotate toward the same side and works with the external obliques for trunk stability.',['sidePlank','pallof'])]},
 quads:{name:'Quadriceps',latin:'Quadriceps femoris',description:'Four muscles at the front of the thigh straighten your knee. The rectus femoris also helps flex the hip.',growth:'Combine a squat pattern with knee extension. Use a comfortable range, and avoid claims that toe position isolates the inner or outer head.',parts:[part('Rectus femoris','The central superficial head crosses both the hip and knee. It straightens the knee and assists lifting the thigh.',['legExtension','splitSquat']),part('Vastus lateralis','The outer thigh head is a powerful knee extensor. It works alongside the other quadriceps during squats and extensions.',['squat','legExtension']),part('Vastus medialis','The inner thigh head contributes to knee extension and patellar control. It is not independently isolated with foot angle.',['splitSquat','legExtension']),part('Vastus intermedius','A deeper head beneath the rectus femoris. It contributes to knee extension throughout leg movements.',['legExtension','squat'])]},
 calves:{name:'Calves',latin:'Gastrocnemius & soleus',description:'Push the foot downward at the ankle to help you walk, run and rise onto your toes.',growth:'Train with both straight and bent knees. Use a controlled stretch and full comfortable ankle motion instead of bouncing.',parts:[part('Gastrocnemius · medial','The inner superficial head crosses the knee and ankle. It contributes to ankle plantarflexion and assists knee flexion.',['standingCalf','seatedCalf']),part('Gastrocnemius · lateral','The outer superficial head shares the same main actions. Both heads work during calf raises.',['standingCalf','seatedCalf']),part('Soleus','A deep calf muscle that crosses the ankle only. It works with either knee position and takes a greater relative role with bent knees.',['seatedCalf','standingCalf'])]},
 back:{name:'Back',latin:'Latissimus dorsi, trapezius & more',description:'A connected set of muscles moves the arms and shoulder blades and supports the spine during lifting.',growth:'Include a vertical pull, a horizontal row and controlled trunk work. Build loading gradually and avoid forcing range through the lower back.',parts:[part('Latissimus dorsi','The broad side-back muscle brings the arm down toward the torso and helps move it behind you.',['pulldown','row']),part('Trapezius','Upper fibers elevate the shoulder blade; middle fibers retract it; lower fibers assist upward rotation and depression with other muscles.',['shrug','row']),part('Rhomboids','Connect the spine to the inner edge of the shoulder blade, helping retract and control the scapula.',['row','reverseFly']),part('Spinal erectors','Long muscles beside the spine that extend and stabilize the trunk. They work during hip hinges and posture control.',['birdDog','rdl'])]},
 glutes:{name:'Glutes',latin:'Gluteus maximus, medius & minimus',description:'Extend and stabilize the hip. They help you stand up, climb stairs and keep the pelvis controlled on one leg.',growth:'Combine hip extension with single-leg work and hip abduction. Increase load as control and tolerance improve.',parts:[part('Gluteus maximus','The largest glute muscle extends the hip and helps rotate the thigh outward. It contributes to squats, hinges and hip thrusts.',['hipThrust','splitSquat']),part('Gluteus medius','On the side of the pelvis, it abducts the hip and helps keep the pelvis level when standing on one leg.',['hipAbduction','splitSquat']),part('Gluteus minimus','A smaller, deeper muscle beneath the medius. It assists hip abduction and pelvic stability.',['hipAbduction','splitSquat'])]},
 hamstrings:{name:'Hamstrings',latin:'Biceps femoris, semitendinosus & semimembranosus',description:'Most hamstrings cross the hip and knee, extending the hip and bending the knee. The short head of biceps femoris crosses only the knee.',growth:'Combine a hip hinge and a knee curl to train both major functions. Increase load slowly and control the lengthening phase.',parts:[part('Biceps femoris · long head','The outer long head crosses the hip and knee. It extends the hip, flexes the knee and helps rotate the bent leg outward.',['rdl','legCurl']),part('Biceps femoris · short head','This outer head starts on the thigh bone and crosses only the knee. Knee curls train its primary action.',['legCurl','legCurl']),part('Semitendinosus','The more superficial inner hamstring assists hip extension, knee flexion and inward rotation of the bent leg.',['rdl','legCurl']),part('Semimembranosus','The deeper inner hamstring shares the hip-extension and knee-flexion roles and contributes to knee control.',['legCurl','rdl'])]}
};
